export function fullWorkspace(model,themes){const layouts={};for(const theme of themes)for(const room of theme.rooms){const layout=model.upgradeBlendModes(model.initial(theme.id));layout.roomId=room.id;const first=Object.values(layout.placements)[0];for(let i=5;i<100;i++)layout.placements['instance-00000000-0000-4000-8000-'+String(i).padStart(12,'0')]={...first};layouts[room.id]=layout;}return model.workspace({version:11,active:Object.values(layouts)[0],layouts,view:model.view(),savedLayouts:Object.values(layouts).slice(0,20).map((layout,i)=>({name:'Synthetic '+i,layout}))});}
